package hu.bankmonitor.payments.idempotency;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;

import java.util.Objects;

/**
 * One client-supplied Idempotency Key, how far the work behind it has got, and the
 * response a repeat of it is owed.
 *
 * <p>The row is the lock. A unique constraint on {@link #getIdempotencyKey() the key} is
 * what serialises two requests arriving at once: both reach the insert, the database
 * refuses one of them, and the refusal — not a preceding read — is how the duplicate is
 * discovered. No application-level lock is involved anywhere in this slice.
 *
 * <p><b>The key is not the primary key, which is not an oversight.</b> Spring Data decides
 * whether {@code save} inserts or merges from whether the identifier is already set, so an
 * entity carrying an assigned key would be saved through {@code merge} — a {@code SELECT}
 * before every {@code INSERT}, and a silent {@code UPDATE} over a live claim when the row
 * it found belongs to somebody else's in-flight request. The surrogate identifier keeps
 * the claim a bare insert, and the named unique constraint keeps the mutual exclusion.
 *
 * <p>There is deliberately no timestamp. The status is the single answer to how far a
 * claim has got, and nothing here reads a clock yet; the reaper that would sweep claims
 * stranded by a crash is deferred, and is the ticket that should add the column with a
 * reader to shape it. {@code docs/deferred.md} has the reasoning.
 *
 * <p>There is also deliberately no mutator. Every transition this record makes is a
 * conditional or guarded update issued by {@link IdempotencyClaims}, because each one has
 * to be atomic against a concurrent duplicate — a setter would offer a second way to make
 * the same transition that quietly is not.
 */
@Entity
@Table(name = "idempotency_records")
class IdempotencyRecord {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	private Long id;

	@Column(length = 36)
	private String idempotencyKey;

	@Column(length = 64)
	private String payloadHash;

	// If left unannotated, JPA stores the status by ordinal. See design decision 29.
	@Enumerated(EnumType.STRING)
	@JdbcTypeCode(SqlTypes.VARCHAR)
	private IdempotencyStatus status;

	@Column(length = 4000)
	private String responseBody;

	protected IdempotencyRecord() {
		// required by JPA
	}

	/**
	 * Claims a key, which is the only way a record comes into being: {@code IN_PROGRESS},
	 * with no response yet and the hash of the payload the claim was made for.
	 *
	 * <p>The hash is stored rather than the payload because the only question ever asked
	 * of it is whether a later request carrying this key means the same thing.
	 */
	IdempotencyRecord(String idempotencyKey, String payloadHash) {
		this.idempotencyKey = Objects.requireNonNull(idempotencyKey, "a claim is made on a key");
		this.payloadHash = Objects.requireNonNull(payloadHash, "a claim is made for a payload");
		this.status = IdempotencyStatus.IN_PROGRESS;
	}

	Long getId() {
		return id;
	}

	/** The value the client sent as {@code X-Idempotency-Key}. Unique across the table. */
	String getIdempotencyKey() {
		return idempotencyKey;
	}

	/**
	 * What the request said, reduced to the one comparison made against it: a repeat of
	 * this key carrying a different hash is a client mistake, not a retry.
	 */
	String getPayloadHash() {
		return payloadHash;
	}

	IdempotencyStatus getStatus() {
		return status;
	}

	/** The response the original request produced, present only once it has {@code SUCCEEDED}. */
	String getResponseBody() {
		return responseBody;
	}
}
package hu.bankmonitor.payments.idempotency;

import org.springframework.data.jpa.repository.Modifying;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.Repository;

/**
 * Persistence for {@link IdempotencyRecord}, package-private so that reaching it from
 * another slice does not compile (design decision 30).
 *
 * <p>The bare {@link Repository} marker rather than {@code JpaRepository}, on
 * {@link hu.bankmonitor.payments.accounts.Account}'s precedent: every method here has a
 * call site in {@link IdempotencyClaims} today. The lookup that reads a row after the
 * constraint has refused an insert arrives with ticket 17, which is the first thing that
 * has a question to ask of it.
 *
 * <p>Every transition is written as an update guarded on the status it is leaving, rather
 * than by loading the record and setting a field. A read-modify-write would decide the
 * outcome in application memory, where two concurrent retries can both decide they won;
 * these decide it in the database, and the row count says which caller it was.
 */
interface IdempotencyRecordRepository extends Repository<IdempotencyRecord, Long> {

	/** Claims a key, which is how a record comes to exist. The unique constraint is the test. */
	IdempotencyRecord save(IdempotencyRecord record);

	/**
	 * Takes a failed key back to {@code IN_PROGRESS}, and reports whether this caller was
	 * the one that took it.
	 *
	 * <p>The guard on {@code FAILED} is the whole mechanism. Design decision 5 records the
	 * race it closes: two retries of the same failed key both read {@code FAILED} and both
	 * proceed, and the second one moves the money a second time. Here the loser's update
	 * matches nothing and returns {@code 0}.
	 *
	 * @return {@code 1} for the caller that reclaimed the key, {@code 0} for every other
	 */
	@Modifying
	@Query("""
			UPDATE IdempotencyRecord claim
			   SET claim.status = hu.bankmonitor.payments.idempotency.IdempotencyStatus.IN_PROGRESS
			 WHERE claim.idempotencyKey = :idempotencyKey
			   AND claim.status = hu.bankmonitor.payments.idempotency.IdempotencyStatus.FAILED
			""")
	int reclaimFailed(String idempotencyKey);

	/**
	 * Stores the response the claimed work produced and closes the claim.
	 *
	 * <p>Unguarded on status, unlike {@link #reclaimFailed}, because it has no contenders:
	 * the caller holds the claim, and a key can only be held once. The conditional update is
	 * for the transitions several callers race for, not for the ones the winner makes
	 * afterwards.
	 *
	 * <p>The count is still returned, for the other thing a rows-affected number can say:
	 * <em>no row carries this key at all</em>. That is not a race, it is a caller marking
	 * the wrong key — and the row it meant to mark stays where it was. {@link
	 * IdempotencyClaims} turns it into an exception rather than a silent no-op.
	 *
	 * @return {@code 1} when the claim was closed, {@code 0} when no row carries the key
	 */
	@Modifying
	@Query("""
			UPDATE IdempotencyRecord claim
			   SET claim.status = hu.bankmonitor.payments.idempotency.IdempotencyStatus.SUCCEEDED,
			       claim.responseBody = :responseBody
			 WHERE claim.idempotencyKey = :idempotencyKey
			""")
	int markSucceeded(String idempotencyKey, String responseBody);

	/**
	 * Releases the claim for a retry to take. Unguarded on status, and counted, for the same
	 * reasons as {@link #markSucceeded}.
	 *
	 * @return {@code 1} when the claim was released, {@code 0} when no row carries the key
	 */
	@Modifying
	@Query("""
			UPDATE IdempotencyRecord claim
			   SET claim.status = hu.bankmonitor.payments.idempotency.IdempotencyStatus.FAILED
			 WHERE claim.idempotencyKey = :idempotencyKey
			""")
	int markFailed(String idempotencyKey);
}
package hu.bankmonitor.payments.idempotency;

/**
 * How far a claimed Idempotency Key has got, and the whole of what a duplicate request is
 * answered from.
 *
 * <p>{@link #IN_PROGRESS} is the only state a claim is made in; the other two are terminal
 * and mean opposite things to a retry. {@code SUCCEEDED} is final in both directions — the
 * work happened and its response is stored, so a repeat replays it. {@code FAILED} is
 * terminal for <em>this</em> attempt only: design decision 5 makes it explicitly
 * retryable, which is what lets any reservation-time failure be recovered by resubmitting
 * the same key.
 */
enum IdempotencyStatus {

	/** Claimed, and the work it stands for has not finished. A duplicate is told to wait. */
	IN_PROGRESS,

	/** The work happened once. Its response is stored and every later duplicate replays it. */
	SUCCEEDED,

	/** The attempt did not finish. The key may be claimed again — exactly once. */
	FAILED
}
/**
 * Replay protection for client-supplied idempotency keys, so that retrying a request
 * never moves money twice.
 *
 * <p>The record of a key, and the mechanics of claiming one — and nothing else. This
 * package exports no type: every class in it is package-private, so the storage and the
 * transaction boundaries that make a claim mutually exclusive cannot be reached from
 * another slice at all.
 *
 * <p>The port design decision 3 describes — the operation that runs a body once per key
 * and returns the first result to every later caller — is not here yet. It arrives with
 * the first caller that has a use for it, which is the duplicate resolution of ticket 17.
 */
package hu.bankmonitor.payments.idempotency;

