	 * the member in the OpenAPI document: unlike the RFC 9457 members around it, this name
	 * is this codebase's own invention, and renaming it here has to rename it there.
	 */
	static final String VALIDATION_ERRORS = "errors";

	private static final URI UNNAMED = URI.create("about:blank");

	private static final String INTERNAL_ERROR_DETAIL =
			"The request could not be completed. Nothing was changed.";

	private static final String NO_ENDPOINT_DETAIL = "This API has no endpoint at that path.";

	/** Spring's own wording for a body that failed its constraints, reused where a body failed the deserializer. */
	private static final String INVALID_CONTENT_DETAIL = "Invalid request content.";

	private static final String INVALID_VALUE = "Invalid value.";

